// Reproduces the two guarantee violations on the failure+retry paths.
import { createQueue, createDedup, createPump, createSink } from './src/index.js'

// --- Bug 1: effectively-once ---
// Attempt 1 reaches the sink (emit), then processMessage reports failure.
// The retry re-emits -> the same id is delivered twice.
{
  const queue = createQueue()
  const sink = createSink()
  const dedup = createDedup({ windowMs: 100 })
  let calls = 0
  let t = 0
  const pump = createPump({
    queue, dedup, sink, clock: { now: () => t },
    processMessage: () => { calls += 1; return false },
    maxAttempts: 3,
  })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  pump.run(10)
  t = 100; pump.run(10)
  t = 300; pump.run(10)
  console.log('[bug1] delivered =', sink.deliveredIds(), '| downstream calls =', calls)
  console.log('[bug1] hasDuplicate =', sink.hasDuplicate())
}

// --- Bug 2: per-key ordering across retries ---
// m1(K) fails and waits for retry; m2(K), enqueued after it, overtakes it.
{
  const queue = createQueue()
  const sink = createSink()
  const dedup = createDedup({ windowMs: 100000 })
  let t = 0
  const pump = createPump({
    queue, dedup, sink, clock: { now: () => t },
    processMessage: (m) => m.key !== 'K',
    maxAttempts: 2,
  })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  pump.run(10)          // m1 emitted, fails, requeued to the tail
  queue.enqueue({ id: 'm2', key: 'K', payload: 2 })
  t = 100; pump.run(10) // m2 overtakes m1
  console.log('[bug2] delivered =', sink.deliveredIds(), '(expected m1 before m2)')
}

/**
 * FIFO message queue. Messages are { id, key, payload }. dequeue removes and
 * returns the oldest message whose id has not been finalized; ack finalizes a
 * message; failed messages are put back on the queue for a later retry.
 *
 * Per-key ordering: a message is only dequeued once no older pending message
 * with the same key exists, so a message waiting for a retry keeps its later
 * same-key messages blocked until it is finalized. requeue() places a failed
 * message back at the head of its key's lane, so the enqueue order inside a
 * key survives the retry detour. When a `now` timestamp is passed, messages
 * whose retryAt is still in the future are left in place (and keep blocking
 * their key) until they come due.
 */
export function createQueue() {
  const entries = []
  const done = new Set()
  return {
    enqueue(message) {
      entries.push({ ...message, attempts: message.attempts ?? 0 })
    },
    dequeue(now) {
      for (let i = 0; i < entries.length; i++) {
        const entry = entries[i]
        if (done.has(entry.id)) continue
        if (now !== undefined && entry.retryAt !== undefined && now < entry.retryAt) continue
        let blocked = false
        for (let j = 0; j < i; j++) {
          const older = entries[j]
          if (!done.has(older.id) && older.key === entry.key) {
            blocked = true
            break
          }
        }
        if (blocked) continue
        return entries.splice(i, 1)[0]
      }
      return null
    },
    ack(id) {
      done.add(id)
    },
    requeue(message) {
      // The requeued message is the oldest pending message of its key (dequeue
      // only returns unblocked messages), so putting it ahead of the first
      // pending same-key entry restores the exact per-key order.
      let at = entries.length
      for (let i = 0; i < entries.length; i++) {
        if (!done.has(entries[i].id) && entries[i].key === message.key) {
          at = i
          break
        }
      }
      entries.splice(at, 0, message)
    },
    pending() {
      return entries.filter((entry) => !done.has(entry.id))
    },
  }
}

/**
 * Delivery pump: dequeue → skip duplicates → deliver → ack + record, or requeue
 * with backoff on failure. The delivery attempt is recorded in the sink before
 * the downstream is called, and the dedup guard is armed at the same moment:
 * once an id has been emitted, a later retry of it is suppressed instead of
 * re-delivered. The pump cannot know whether the downstream accepted the
 * message before the attempt failed, so it never re-emits an id and never
 * calls the downstream a second time for it. Retries of an already-emitted id
 * only carry the attempt bookkeeping forward until the message is abandoned at
 * maxAttempts; fresh producer duplicates of a delivered id are dropped.
 */
import { retryWithBackoff } from './retry.js'

export function createPump({ queue, dedup, sink, clock, processMessage, maxAttempts = 3 }) {
  const backoff = retryWithBackoff(clock)
  const emitted = new Set()
  return {
    run(steps = Infinity) {
      for (let i = 0; i < steps; i++) {
        const now = clock.now()
        const message = queue.dequeue(now)
        if (message === null) break
        if (emitted.has(message.id) || dedup.isDuplicate(message.id, now)) {
          // Already emitted on an earlier attempt (or a duplicate id produced
          // upstream): never re-emit, never call the downstream again.
          if (message.attempts > 0 || message.retryAt !== undefined) {
            // A retry of a message this pump already attempted: keep the
            // backoff bookkeeping going, then abandon it at maxAttempts.
            message.attempts += 1
            if (message.attempts >= maxAttempts) {
              queue.ack(message.id)
              sink.failed(message)
            } else {
              message.retryAt = now + backoff.delayFor(message.attempts)
              queue.requeue(message)
            }
          } else {
            // A fresh duplicate of an already-delivered id: drop it.
            queue.ack(message.id)
          }
          continue
        }
        sink.emit(message)
        emitted.add(message.id)
        dedup.record(message.id, now)
        const ok = processMessage(message)
        if (!ok) {
          message.attempts += 1
          if (message.attempts >= maxAttempts) {
            queue.ack(message.id)
            sink.failed(message)
            continue
          }
          message.retryAt = now + backoff.delayFor(message.attempts)
          queue.requeue(message)
          continue
        }
        queue.ack(message.id)
      }
    },
  }
}

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createQueue, createDedup, createPump, createSink } from '../src/index.js'

// Guarantee 1: effectively-once. A delivery attempt that fails after the
// downstream has already accepted the message must never be re-delivered on
// retry. The pump cannot know whether the downstream accepted before the
// attempt failed, so it never re-emits an id it has already emitted and never
// calls the downstream a second time for it.

test('guarantee: a failed attempt is never re-delivered on retry', () => {
  const queue = createQueue()
  const sink = createSink()
  const dedup = createDedup({ windowMs: 100 })
  let downstreamCalls = 0
  let currentTime = 0
  const clock = { now: () => currentTime }
  const pump = createPump({
    queue,
    dedup,
    sink,
    clock,
    processMessage: () => {
      downstreamCalls += 1
      return false // the attempt fails after the downstream already accepted
    },
    maxAttempts: 3,
  })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })

  pump.run(10) // t=0: delivered once, attempt fails, retry scheduled at t=100
  currentTime = 100
  pump.run(10) // retry is suppressed: the id was already emitted
  currentTime = 300
  pump.run(10) // last retry is suppressed; the message is abandoned

  assert.deepEqual(sink.deliveredIds(), ['m1'])
  assert.equal(sink.hasDuplicate(), false)
  assert.equal(downstreamCalls, 1) // retry must not re-deliver
  assert.deepEqual(sink.failedIds(), ['m1'])
})

test('guarantee: no re-delivery even when the dedup window expires mid-retry', () => {
  const queue = createQueue()
  const sink = createSink()
  const dedup = createDedup({ windowMs: 50 })
  let currentTime = 0
  const clock = { now: () => currentTime }
  const pump = createPump({ queue, dedup, sink, clock, processMessage: () => false, maxAttempts: 2 })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })

  pump.run(10) // t=0: delivered once, attempt fails
  currentTime = 100 // past both the 50ms dedup window and the first backoff
  pump.run(10)

  assert.deepEqual(sink.deliveredIds(), ['m1'])
  assert.equal(sink.hasDuplicate(), false)
})

test('guarantee: a duplicate id enqueued while the original waits is dropped', () => {
  const queue = createQueue()
  const sink = createSink()
  const dedup = createDedup({ windowMs: 100000 })
  let currentTime = 0
  const clock = { now: () => currentTime }
  const pump = createPump({ queue, dedup, sink, clock, processMessage: () => false, maxAttempts: 2 })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })

  pump.run(10) // m1 delivered once, then waits for retry
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 }) // duplicate of a delivered id

  currentTime = 100
  pump.run(10) // m1 abandoned; duplicate never delivered

  assert.deepEqual(sink.deliveredIds(), ['m1'])
  assert.equal(sink.hasDuplicate(), false)
})

// Guarantee 2: per-key ordering. For any two messages with the same key, the
// earlier enqueued one is delivered before the later one, even across retries.

test('guarantee: a later same-key message waits for the retrying one', () => {
  const queue = createQueue()
  const sink = createSink()
  const dedup = createDedup({ windowMs: 100000 })
  let currentTime = 0
  const clock = { now: () => currentTime }
  const pump = createPump({ queue, dedup, sink, clock, processMessage: () => false, maxAttempts: 2 })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm2', key: 'K', payload: 2 })

  pump.run(10) // t=0: m1 delivered, then waits; m2 must not overtake it
  assert.deepEqual(sink.deliveredIds(), ['m1'])

  currentTime = 100
  pump.run(10) // m1 abandoned; only then does m2 flow
  assert.deepEqual(sink.deliveredIds(), ['m1', 'm2'])
})

test('guarantee: a same-key message enqueued while the head waits stays behind it', () => {
  const queue = createQueue()
  const sink = createSink()
  const dedup = createDedup({ windowMs: 100000 })
  let currentTime = 0
  const clock = { now: () => currentTime }
  const pump = createPump({ queue, dedup, sink, clock, processMessage: () => false, maxAttempts: 2 })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })

  pump.run(10) // m1 delivered, fails, waits for retry
  queue.enqueue({ id: 'm2', key: 'K', payload: 2 })
  currentTime = 50
  pump.run(10) // m1 not due yet; m2 must not overtake it
  assert.deepEqual(sink.deliveredIds(), ['m1'])

  currentTime = 100
  pump.run(10) // m1 abandoned; m2 follows
  assert.deepEqual(sink.deliveredIds(), ['m1', 'm2'])
})

test('guarantee: other keys keep flowing while a message waits for retry', () => {
  const queue = createQueue()
  const sink = createSink()
  const dedup = createDedup({ windowMs: 100000 })
  let currentTime = 0
  const clock = { now: () => currentTime }
  const pump = createPump({
    queue,
    dedup,
    sink,
    clock,
    processMessage: (m) => m.key !== 'K1', // K1 fails, other keys succeed
    maxAttempts: 2,
  })
  queue.enqueue({ id: 'm1', key: 'K1', payload: 1 })
  pump.run(10) // m1 delivered, fails, waits for retry

  queue.enqueue({ id: 'm2', key: 'K2', payload: 2 })
  pump.run(10) // K2 is independent of K1's head-of-line hold
  assert.deepEqual(sink.deliveredIds(), ['m1', 'm2'])
})

// Queue-level behavior backing the ordering guarantee.

test('queue: requeue restores the head of the key lane', () => {
  const queue = createQueue()
  queue.enqueue({ id: 'a', key: 'K', payload: 1 })
  queue.enqueue({ id: 'b', key: 'K', payload: 2 })
  const first = queue.dequeue()
  assert.equal(first.id, 'a')
  queue.requeue(first)
  assert.equal(queue.dequeue().id, 'a') // not 'b'
})

test('queue: a not-due message keeps blocking its key until it comes due', () => {
  const queue = createQueue()
  queue.enqueue({ id: 'a', key: 'K', payload: 1 })
  queue.enqueue({ id: 'b', key: 'K', payload: 2 })
  const first = queue.dequeue()
  first.retryAt = 100
  queue.requeue(first)
  assert.equal(queue.dequeue(0), null) // 'a' not due, so 'b' stays blocked
  assert.equal(queue.dequeue(100).id, 'a') // due again before 'b'
  queue.ack('a')
  assert.equal(queue.dequeue(100).id, 'b')
})

import { createQueue, createDedup, createPump, createSink } from './src/index.js'

const queue = createQueue()
const sink = createSink()
const dedup = createDedup({ windowMs: 60 })
let t = 0
let attemptsByKey = {}
const pump = createPump({
  queue, dedup, sink, clock: { now: () => t },
  processMessage: (m) => {
    attemptsByKey[m.id] = (attemptsByKey[m.id] ?? 0) + 1
    return attemptsByKey[m.id] > 3 || m.key === 'Z' ? m.key === 'Z' : false
  },
  maxAttempts: 5,
})

// Interleave three keys; A-messages fail repeatedly, a duplicate sneaks in.
for (let i = 1; i <= 4; i++) {
  queue.enqueue({ id: 'A' + i, key: 'A', payload: i })
  queue.enqueue({ id: 'B' + i, key: 'B', payload: i })
  queue.enqueue({ id: 'C' + i, key: 'C', payload: i })
}
queue.enqueue({ id: 'A1', key: 'A', payload: 1 }) // duplicate id

for (let step = 0; step < 40; step++) {
  pump.run(25)
  t += 70 // advance past backoff and past the 60ms dedup window each round
}

const ids = sink.deliveredIds()
const firstIndexOf = (id) => ids.indexOf(id)
let ok = true
for (const key of ['A', 'B', 'C']) {
  const lane = ids.filter((id) => id.startsWith(key))
  const expected = [1, 2, 3, 4].map((i) => key + i)
  if (JSON.stringify(lane) !== JSON.stringify(expected)) {
    ok = false
    console.log(`key ${key} lane:`, lane, 'expected:', expected)
  }
}
const dup = ids.some((id, i) => ids.indexOf(id) !== i)
console.log('per-key order held:', ok, '| any duplicate id:', dup, '| total delivered:', ids.length)
console.log('failed:', sink.failedIds().join(','))

